-- Seed idempotente de catálogo e ofertas DEMONSTRATIVAS. Preços não são reais.
USE churrasplan;


-- Cobertura DEMONSTRATIVA de preços para todo o catálogo padrão.
-- Estes valores existem apenas para desenvolvimento/testes locais; não são preços reais.
-- Em produção, carregue ofertas verificadas de parceiros/fontes autorizadas.
-- ============================================================
-- Fases 3-6: catálogo genérico e planos-base
-- ============================================================
UPDATE produtos
SET tipo_produto = 'generico'
WHERE produto_pai_id IS NULL AND (tipo_produto IS NULL OR tipo_produto <> 'comercial');

VALUES (
    'gratuito', 'Gratuito', 'usuario', 0.00,
    JSON_OBJECT(
        'planejamento', TRUE,
        'historico', TRUE,
        'convites', TRUE,
        'onde_comprar', TRUE
    ), TRUE
)
ON DUPLICATE KEY UPDATE
    nome = VALUES(nome), publico_alvo = VALUES(publico_alvo),
    preco_mensal = VALUES(preco_mensal), recursos = VALUES(recursos), ativo = TRUE;

VALUES (
    'parceiro', 'Parceiro', 'parceiro', 0.00,
    JSON_OBJECT(
        'painel_estabelecimento', TRUE,
        'produtos_comerciais', TRUE,
        'ofertas', TRUE
    ), TRUE
)
ON DUPLICATE KEY UPDATE
    nome = VALUES(nome), publico_alvo = VALUES(publico_alvo),
    preco_mensal = VALUES(preco_mensal), recursos = VALUES(recursos), ativo = TRUE;

-- Os preços acima são apenas dados demonstrativos. Para produção, cadastre
